Here is the commit message:
habanalabs/gaudi: Fix a potential use after free in
 gaudi_memset_device_memory

Our code analyzer reported a uaf.

In gaudi_memset_device_memory, cb is get via hl_cb_kernel_create()
with 2 refcount.
If hl_cs_allocate_job() failed, the execution runs into release_cb
branch. One ref of cb is dropped by hl_cb_put(cb) and could be freed
if other thread also drops one ref. Then cb is used by cb->id later,
which is a potential uaf.

My patch add a variable 'id' to accept the value of cb->id before the
hl_cb_put(cb) is called, to avoid the potential uaf.

Fixes: 423815bf02e25 ("habanalabs/gaudi: remove PCI access to SM block")
Signed-off-by: Lv Yunlong <lyl2019@mail.ustc.edu.cn>
Reviewed-by: Oded Gabbay <ogabbay@kernel.org>
Signed-off-by: Oded Gabbay <ogabbay@kernel.org>

Here is the root cause:
The bug is caused by a potential use-after-free (UAF) situation where the reference count of the callback object (`cb`) is decremented, and if another thread also decrements it, `cb` could be freed. Subsequently, the code attempts to access `cb->id`, which may lead to accessing invalid memory.

Here is the patch:

 static int gaudi_memset_device_memory(struct hl_device *hdev, u64 addr,
 					u32 size, u64 val)
 {
 	struct packet_lin_dma *lin_dma_pkt;
 	struct hl_cs_job *job;
 	u32 cb_size, ctl, err_cause;
 	struct hl_cb *cb;
+	u64 id;
 	int rc;

 	cb = hl_cb_kernel_create(hdev, PAGE_SIZE, false);
 	if (!cb)
 		return -EFAULT;

 	lin_dma_pkt = cb->kernel_address;
 	memset(lin_dma_pkt, 0, sizeof(*lin_dma_pkt));
 	cb_size = sizeof(*lin_dma_pkt);

 	ctl = FIELD_PREP(GAUDI_PKT_CTL_OPCODE_MASK, PACKET_LIN_DMA);
 	ctl |= FIELD_PREP(GAUDI_PKT_LIN_DMA_CTL_MEMSET_MASK, 1);
 	ctl |= FIELD_PREP(GAUDI_PKT_LIN_DMA_CTL_LIN_MASK, 1);
 	ctl |= FIELD_PREP(GAUDI_PKT_CTL_MB_MASK, 1);
 	ctl |= FIELD_PREP(GAUDI_PKT_CTL_RB_MASK, 1);

 	lin_dma_pkt->ctl = cpu_to_le32(ctl);
 	lin_dma_pkt->src_addr = cpu_to_le64(val);
 	lin_dma_pkt->dst_addr |= cpu_to_le64(addr);
 	lin_dma_pkt->tsize = cpu_to_le32(size);

 	job = hl_cs_allocate_job(hdev, QUEUE_TYPE_EXT, true);
 	if (!job) {
 		dev_err(hdev->dev, "Failed to allocate a new job\n");
 		rc = -ENOMEM;
 		goto release_cb;
 	}

 	/* Verify DMA is OK */
 	err_cause = RREG32(mmDMA0_CORE_ERR_CAUSE);
 	if (err_cause && !hdev->init_done) {
 		dev_dbg(hdev->dev,
 			"Clearing DMA0 engine from errors (cause 0x%x)\n",
 			err_cause);
 		WREG32(mmDMA0_CORE_ERR_CAUSE, err_cause);
 	}

 	job->id = 0;
 	job->user_cb = cb;
 	atomic_inc(&job->user_cb->cs_cnt);
 	job->user_cb_size = cb_size;
 	job->hw_queue_id = GAUDI_QUEUE_ID_DMA_0_0;
 	job->patched_cb = job->user_cb;
 	job->job_cb_size = job->user_cb_size + sizeof(struct packet_msg_prot);

 	hl_debugfs_add_job(hdev, job);

 	rc = gaudi_send_job_on_qman0(hdev, job);
 	hl_debugfs_remove_job(hdev, job);
 	kfree(job);
 	atomic_dec(&cb->cs_cnt);

 	/* Verify DMA is OK */
 	err_cause = RREG32(mmDMA0_CORE_ERR_CAUSE);
 	if (err_cause) {
 		dev_err(hdev->dev, "DMA Failed, cause 0x%x\n", err_cause);
 		rc = -EIO;
 		if (!hdev->init_done) {
 			dev_dbg(hdev->dev,
 				"Clearing DMA0 engine from errors (cause 0x%x)\n",
 				err_cause);
 			WREG32(mmDMA0_CORE_ERR_CAUSE, err_cause);
 		}
 	}

 release_cb:
+	id = cb->id;
 	hl_cb_put(cb);
-	hl_cb_destroy(hdev, &hdev->kernel_cb_mgr, cb->id << PAGE_SHIFT);
+	hl_cb_destroy(hdev, &hdev->kernel_cb_mgr, id << PAGE_SHIFT);

 	return rc;
 }



